const CACHE='wild-pocket-v53';
const SHELL=['./','./index.html','./style.css','./app.js','./animals.js','./habitats.js','./stories.js','./sounds.js','./photos.js','./manifest.webmanifest','./icon-192.png','./icon-512.png'];
const PHOTOS=['lion','leopard','cheetah','hyena','elephant','buffalo','rhino','hippo','giraffe','zebra','wildebeest','impala','thomson','grant','topi','eland','warthog','baboon','ostrich','crocodile','waterbuck','hartebeest','dikdik','jackal','serval','bateared','crane','secretary','bustard','wilddog','vervet','reedbuck','kudu','gerenuk','duiker','honeybadger','mongoose','caracal','aardwolf','flamingo','bushbuck','genet','civet','groundhornbill','martialeagle','bateleur','fisheagle','roller','starling','greaterflamingo','vulture','egyptiangoose','yellowstork','ibis','monitor'].map(id=>'./assets/'+id+'.jpg');PHOTOS.push(...['elephant','giraffe','wildebeest','ostrich'].map(id=>'./assets/'+id+'-story.jpg'));importScripts('./photos.js');PHOTOS.push(...Object.values(GALLERY).flat().map(p=>p.file));importScripts('./sounds.js');const SOUNDS=[...new Set(Object.values(CALLS).map(c=>c.file))];const ALL=[...SHELL,...PHOTOS,...SOUNDS];
self.addEventListener('install',event=>event.waitUntil((async()=>{const c=await caches.open(CACHE);await c.addAll(SHELL);const oldKeys=(await caches.keys()).filter(k=>k.startsWith('wild-pocket-')&&k!==CACHE);for(const path of [...PHOTOS,...SOUNDS]){for(const key of oldKeys){const hit=await (await caches.open(key)).match(path);if(hit){await c.put(path,hit);break}}}await self.skipWaiting()})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{await self.clients.claim();const windows=await self.clients.matchAll({type:'window'});windows.forEach(w=>{w.navigate(w.url).catch(()=>{})})})()));
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(u.origin!==self.location.origin||event.request.method!=='GET')return;event.respondWith((async()=>{const c=await caches.open(CACHE);const hit=await c.match(event.request,{ignoreSearch:true});if(hit)return hit;try{return await fetch(event.request)}catch(e){if(event.request.mode==='navigate'){const home=await c.match('./');if(home)return home}throw e}})())});
self.addEventListener('message',event=>{const p=event.ports[0];if(!p)return;event.waitUntil((async()=>{try{const c=await caches.open(CACHE);if(event.data.type==='DOWNLOAD'){for(let i=0;i<ALL.length;i++){const path=ALL[i];if(!await c.match(path)){const response=await fetch(path,{cache:'reload'});if(!response.ok||response.redirected)throw Error('部分文件无法获取，请联网后重试');const mime=response.headers.get('content-type')||'';if(path.endsWith('.jpg')&&!mime.startsWith('image/'))throw Error('照片下载失败，请重新打开应用后重试');await c.put(path,response)}p.postMessage({progress:Math.round((i+1)/ALL.length*100),done:i+1,total:ALL.length})}}let cached=0;for(const path of ALL)if(await c.match(path))cached++;p.postMessage({cached,total:ALL.length,complete:cached===ALL.length})}catch(e){p.postMessage({error:e.message})}})())});
